"""Show how the guaranteed triangle lower bound q*sqrt(m)/3 tracks the true count."""
from __future__ import annotations
import math
from itertools import combinations
from typing import List, Tuple

def symmetric_eigenvalues(A: List[List[float]], iters: int = 300) -> List[float]:
    n = len(A); M = [r[:] for r in A]
    for _ in range(iters):
        p, q, off = 0, 1, 0.0
        for i in range(n):
            for j in range(i+1, n):
                if abs(M[i][j]) > off: off, p, q = abs(M[i][j]), i, j
        if off < 1e-14: break
        app, aqq, apq = M[p][p], M[q][q], M[p][q]
        phi = 0.5*math.atan2(2*apq, aqq-app) if aqq != app else math.pi/4
        c, s = math.cos(phi), math.sin(phi)
        for k in range(n):
            a,b = M[k][p],M[k][q]; M[k][p],M[k][q] = c*a-s*b, s*a+c*b
        for k in range(n):
            a,b = M[p][k],M[q][k]; M[p][k],M[q][k] = c*a-s*b, s*a+c*b
    return sorted((M[i][i] for i in range(n)), reverse=True)

def stats(n: int, edges: List[Tuple[int,int]]):
    A = [[0.0]*n for _ in range(n)]
    for u,v in edges: A[u][v]=A[v][u]=1.0
    mu = symmetric_eigenvalues(A); lam = mu[0]; m = len(edges)
    E = {frozenset(e) for e in edges}
    t = sum(1 for a,b,c in combinations(range(n),3)
            if {frozenset((a,b)),frozenset((b,c)),frozenset((a,c))} <= E)
    return lam, m, t

if __name__ == "__main__":
    print(f"{'graph':10}{'q':>8}{'bound q*sqrt(m)/3':>20}{'true t':>10}")
    for r in range(3, 8):
        lam, m, t = stats(r, list(combinations(range(r), 2)))
        q = lam**2 - m
        print(f"K{r:<9}{q:8.2f}{q*math.sqrt(m)/3:20.3f}{t:10}")

"""Empirically confirm lam*q <= 3t on random graphs (never violated)."""
from __future__ import annotations
import math, random
from itertools import combinations
from typing import List, Tuple

def symmetric_eigenvalues(A: List[List[float]], iters: int = 400) -> List[float]:
    n = len(A); M = [r[:] for r in A]
    for _ in range(iters):
        p, q, off = 0, 1, 0.0
        for i in range(n):
            for j in range(i+1, n):
                if abs(M[i][j]) > off: off, p, q = abs(M[i][j]), i, j
        if off < 1e-13: break
        app, aqq, apq = M[p][p], M[q][q], M[p][q]
        phi = 0.5*math.atan2(2*apq, aqq-app) if aqq != app else math.pi/4
        c, s = math.cos(phi), math.sin(phi)
        for k in range(n):
            a,b = M[k][p],M[k][q]; M[k][p],M[k][q] = c*a-s*b, s*a+c*b
        for k in range(n):
            a,b = M[p][k],M[q][k]; M[p][k],M[q][k] = c*a-s*b, s*a+c*b
    return sorted((M[i][i] for i in range(n)), reverse=True)

def sample(n: int, p: float, seed: int) -> None:
    random.seed(seed)
    edges: List[Tuple[int,int]] = [(i,j) for i,j in combinations(range(n),2)
                                   if random.random() < p]
    A = [[0.0]*n for _ in range(n)]
    for u,v in edges: A[u][v]=A[v][u]=1.0
    mu = symmetric_eigenvalues(A); lam = mu[0]; m = len(edges)
    E = {frozenset(e) for e in edges}
    t = sum(1 for a,b,c in combinations(range(n),3)
            if {frozenset((a,b)),frozenset((b,c)),frozenset((a,c))} <= E)
    q = lam**2 - m
    ok = lam*q <= 3*t + 1e-6
    print(f"seed={seed} m={m:3} t={t:3} q={q:7.3f} lam*q={lam*q:8.3f} 3t={3*t:3} ok={ok}")

if __name__ == "__main__":
    for s in range(8):
        sample(10, 0.5, s)

