from __future__ import annotations
import math
from typing import List

def symmetric_eigenvalues(A: List[List[float]], iters: int = 200,
                          tol: float = 1e-14) -> List[float]:
    """Cyclic-Jacobi eigenvalues of a real symmetric matrix, descending."""
    n = len(A)
    M = [row[:] for row in A]
    for _ in range(iters):
        p, q, off = 0, 1, 0.0
        for i in range(n):
            for j in range(i + 1, n):
                if abs(M[i][j]) > off:
                    off, p, q = abs(M[i][j]), i, j
        if off < tol:
            break
        app, aqq, apq = M[p][p], M[q][q], M[p][q]
        phi = 0.5 * math.atan2(2 * apq, aqq - app) if aqq != app else math.pi / 4
        c, s = math.cos(phi), math.sin(phi)
        for k in range(n):
            a, b = M[k][p], M[k][q]
            M[k][p], M[k][q] = c * a - s * b, s * a + c * b
        for k in range(n):
            a, b = M[p][k], M[q][k]
            M[p][k], M[q][k] = c * a - s * b, s * a + c * b
    return sorted((M[i][i] for i in range(n)), reverse=True)

