"""Scatter: lambda^2 vs m for many graphs, with the Nosal line lambda^2 = m."""
import math, random
from itertools import combinations
import matplotlib.pyplot as plt

def jacobi_top(A, iters=300):
    n = len(A); M = [r[:] for r in A]
    for _ in range(iters):
        p, q, off = 0, 1, 0.0
        for i in range(n):
            for j in range(i+1, n):
                if abs(M[i][j]) > off: off, p, q = abs(M[i][j]), i, j
        if off < 1e-13: break
        app, aqq, apq = M[p][p], M[q][q], M[p][q]
        phi = 0.5*math.atan2(2*apq, aqq-app) if aqq != app else math.pi/4
        c, s = math.cos(phi), math.sin(phi)
        for k in range(n):
            a,b = M[k][p],M[k][q]; M[k][p],M[k][q]=c*a-s*b, s*a+c*b
        for k in range(n):
            a,b = M[p][k],M[q][k]; M[p][k],M[q][k]=c*a-s*b, s*a+c*b
    return max(M[i][i] for i in range(n))

def main():
    tri_free, has_tri = [], []
    random.seed(1)
    for _ in range(200):
        n = random.randint(4, 9); p = random.random()
        edges = [(i,j) for i,j in combinations(range(n),2) if random.random()<p]
        A = [[0.0]*n for _ in range(n)]
        for u,v in edges: A[u][v]=A[v][u]=1.0
        lam = jacobi_top(A); m = len(edges)
        E = {frozenset(e) for e in edges}
        t = sum(1 for a,b,c in combinations(range(n),3)
                if {frozenset((a,b)),frozenset((b,c)),frozenset((a,c))}<=E)
        (tri_free if t==0 else has_tri).append((m, lam**2))
    fig, ax = plt.subplots(figsize=(7,7))
    if tri_free: ax.scatter(*zip(*tri_free), c="tab:blue", label="triangle-free", alpha=0.7)
    if has_tri: ax.scatter(*zip(*has_tri), c="tab:red", label="has triangle", alpha=0.5)
    lim = max(m for m,_ in tri_free+has_tri)
    ax.plot([0,lim],[0,lim], "k--", label=r"Nosal line $\lambda^2=m$")
    ax.set_xlabel("edges $m$"); ax.set_ylabel(r"$\lambda^2$")
    ax.set_title("Nosal threshold: triangle-free graphs stay below the line")
    ax.legend(); plt.tight_layout(); plt.savefig("nosal_threshold.png", dpi=140)

if __name__ == "__main__":
    main()

